package studio.solocamera;
/** Persistence and render ordering are privacy guarantees independent of Android drawing. */
public final class PrivacyModelTest {
 static void check(boolean b,String m){if(!b)throw new AssertionError(m);}
 static EditorProject.Caption caption(boolean privacy){EditorProject.Caption c=new EditorProject.Caption();c.type=privacy?"Image":"Text";c.at=500;c.end=3000;c.style=new EditorProject.Clip("privacy:test","Cover",2500);c.style.privacyBlackout=privacy;c.style.privacyWidth=.7;c.style.privacyHeight=.006;c.style.text="Privacy blackout";c.style.textPlaced=true;c.style.textX=.91;c.style.textY=.7;return c;}
 public static void main(String[] args)throws Exception{EditorProject p=new EditorProject();EditorProject.Caption first=caption(true),normal=caption(false),last=caption(true);p.captions.add(first);p.captions.add(normal);p.captions.add(last);java.util.List<EditorProject.Caption> ordered=EditorPrivacy.ordered(p);check(ordered.get(0)==normal&&ordered.get(1)==first&&ordered.get(2)==last,"Opaque covers must follow normal captions and retain mutual order");check(p.captions.get(0)==first,"Ordering mutated editing tracks");EditorProject restored=EditorProject.from(p.json().toString());EditorProject.Caption copy=restored.captions.get(0);check(copy.style.privacyBlackout&&copy.type.equals("Image")&&copy.style.imageUri.isEmpty(),"Privacy object type lost or fake media asset created");check(Math.abs(copy.style.privacyHeight-.006)<1e-9&&copy.style.textX==.91&&copy.at==500&&copy.end==3000,"Geometry/timing drift after saving");org.json.JSONObject legacy=normal.style.json();legacy.remove("privacyBlackout");check(!EditorProject.Clip.from(legacy).privacyBlackout,"Old media became a blackout");System.out.println("PASS opaque-layer ordering, stable multi-cover order, unchanged editing tracks, thin cover geometry/time/position JSON and legacy defaults");}
}
